input.sparql:
SELECT ?p ?label ?ts WHERE {
  ?p rdf:type brick:Temperature_Sensor .
  ?p rdfs:label ?label .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?label WHERE {
  ?p rdfs:label ?label .
  FILTER(contains(?label, "temp") || contains(?label, "Temp"))
} LIMIT 60

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?point ?label ?ts WHERE {
  ?point rdf:type brick:Zone_Air_Temperature_Sensor .
  ?point rdfs:label ?label .
  ?point ref:hasTimeseriesId ?ts .
} ORDER BY ?label

SELECT ?p ?label ?ts WHERE {
  ?p rdfs:label ?label .
  FILTER(contains(?label, "Core") || contains(?label, "core"))
  ?p ref:hasTimeseriesId ?ts .
} ORDER BY ?label

SELECT ?p ?label WHERE {
  ?p rdfs:label ?label .
  FILTER(contains(?label, "VAV"))
} ORDER BY ?label

